import { describe, it, expect } from "vitest";
import {
  parseMemories, sortMemories, selectTab, searchMemories, summarize, tagCounts,
  linkKind, targetLabel, asHorizon, asStatus, asKind, relativeAge, buildGraph,
  DEFAULT_REL, MEMORY_TABS, TAB_LABEL, TAB_BLURB, KINDS, KIND_META,
  type MemoryEntry,
} from "@/features/memory/lib/memory";

const at = (ms: number, over: Partial<MemoryEntry> = {}): MemoryEntry => ({
  id: String(ms * 1_000_000),
  text: "a thought",
  tags: [],
  createdAtMs: ms,
  status: "open",
  horizon: "now",
  kind: "note",
  links: [],
  ...over,
});

describe("parseMemories — the wire `bsc memory list --json` writes", () => {
  it("reads serde's snake_case timestamp, and the camelCase spelling too", () => {
    const rows = parseMemories([
      { id: "1", text: "snake", tags: [], created_at_ms: 500, status: "open", horizon: "now", links: [] },
      { id: "2", text: "camel", tags: [], createdAtMs: 600, status: "open", horizon: "now", links: [] },
    ]);
    expect(rows.map((r) => r.createdAtMs)).toEqual([500, 600]);
  });

  it("accepts a JSON string, a bare array, and an object wrapping one", () => {
    const row = { id: "1", text: "t", created_at_ms: 1 };
    expect(parseMemories(JSON.stringify([row]))).toHaveLength(1);
    expect(parseMemories([row])).toHaveLength(1);
    expect(parseMemories({ memories: [row] })).toHaveLength(1);
  });

  it("reads a legacy bare-string link as `related`, exactly as de_links does in Rust", () => {
    const [m] = parseMemories([{ id: "1", text: "t", links: ["some-record.rs", { ref: "x.rs", rel: "about" }] }]);
    expect(m.links).toEqual([
      { ref: "some-record.rs", rel: DEFAULT_REL },
      { ref: "x.rs", rel: "about" },
    ]);
  });

  it("drops a row it cannot key or show, rather than rendering a blank line", () => {
    expect(parseMemories([{ id: "", text: "no id" }, { id: "1", text: "   " }, { id: "2", text: "ok" }]))
      .toEqual([expect.objectContaining({ id: "2" })]);
  });

  it("returns nothing — never throws — for junk", () => {
    expect(parseMemories("not json")).toEqual([]);
    expect(parseMemories(null)).toEqual([]);
    expect(parseMemories(42)).toEqual([]);
  });

  it("defaults an absent horizon to `now`, status to `open`, and kind to `note`", () => {
    const [m] = parseMemories([{ id: "1", text: "t" }]);
    expect(m.horizon).toBe("now");
    expect(m.status).toBe("open");
    // The memories written before the kind facet must read as UNCLASSIFIED, never as a real kind —
    // silently filing them as lessons would put words in their author's mouth.
    expect(m.kind).toBe("note");
  });
});

describe("asKind — an unknown kind must read as unclassified, never as a real one", () => {
  it("keeps a known kind and falls back to note", () => {
    expect(asKind("lesson")).toBe("lesson");
    expect(asKind("highlight")).toBe("highlight");
    expect(asKind("lessons")).toBe("note");
    expect(asKind(undefined)).toBe("note");
  });
});

describe("the kind vocabulary — the surfaces that enumerate it must agree", () => {
  it("gives every kind a label and a blurb", () => {
    // A kind with no blurb renders a page that cannot say what belongs on it, which is how the
    // lesson/highlight distinction gets lost — the whole reason kind is the axis.
    for (const k of KINDS) {
      expect(KIND_META[k].label.trim().length).toBeGreaterThan(0);
      expect(KIND_META[k].blurb.trim().length).toBeGreaterThan(20);
    }
  });

  it("puts the graph first and every kind after it, with no tab left unlabelled", () => {
    expect(MEMORY_TABS[0]).toBe("graph");
    expect([...MEMORY_TABS].slice(1)).toEqual([...KINDS]);
    for (const tab of MEMORY_TABS) {
      expect(TAB_LABEL[tab]?.trim().length).toBeGreaterThan(0);
      expect(TAB_BLURB[tab]?.trim().length).toBeGreaterThan(20);
    }
  });

  it("mirrors the Rust vocabulary exactly", () => {
    // `bsc_memory::KINDS`, in its reading order. A drift here means the CLI can write a kind the
    // workspace has no page for — a memory that exists and is unreachable.
    expect([...KINDS]).toEqual(["lesson", "highlight", "record", "ambient", "note"]);
  });
});

describe("asHorizon / asStatus — an unknown value must not hide a memory", () => {
  it("reads an unknown horizon as `now`, matching default_horizon", () => {
    expect(asHorizon("sideways")).toBe("now");
    expect(asHorizon(undefined)).toBe("now");
    expect(asHorizon("future")).toBe("future");
  });
  it("reads an unknown status as `open`, never as `done`", () => {
    expect(asStatus("archived")).toBe("open");
    expect(asStatus("done")).toBe("done");
  });
});

describe("sortMemories", () => {
  it("is newest first, the order filter_and_order produces", () => {
    const rows = sortMemories([at(100), at(300), at(200)]);
    expect(rows.map((r) => r.createdAtMs)).toEqual([300, 200, 100]);
  });
  it("breaks a tie on the id, which is also time", () => {
    const a = { ...at(100), id: "111" };
    const b = { ...at(100), id: "222" };
    expect(sortMemories([a, b]).map((r) => r.id)).toEqual(["222", "111"]);
  });
  it("does not mutate its input", () => {
    const input = [at(100), at(300)];
    sortMemories(input);
    expect(input.map((r) => r.createdAtMs)).toEqual([100, 300]);
  });
});

describe("selectTab", () => {
  const lesson = at(1, { kind: "lesson" });
  const highlight = at(2, { kind: "highlight", horizon: "future" });
  const unclassified = at(3, { kind: "note" });

  it("gives each kind page exactly its own kind", () => {
    const all = [lesson, highlight, unclassified];
    expect(selectTab(all, "lesson")).toEqual([lesson]);
    expect(selectTab(all, "highlight")).toEqual([highlight]);
    expect(selectTab(all, "note")).toEqual([unclassified]);
    expect(selectTab(all, "ambient")).toEqual([]);
  });

  it("gives the graph EVERYTHING — it is the whole graph, not a sixth kind", () => {
    const all = [lesson, highlight, unclassified];
    expect(selectTab(all, "graph")).toEqual(all);
  });

  it("ignores horizon, which is a filter within a page and not the axis", () => {
    // highlight is on the `future` horizon and must still appear on its own kind page. Horizon was
    // the axis before; making it one again would put a hope and a lesson on the same page.
    expect(selectTab([lesson, highlight], "highlight")).toEqual([highlight]);
  });

  it("covers every declared tab", () => {
    for (const tab of MEMORY_TABS) expect(() => selectTab([lesson, highlight], tab)).not.toThrow();
  });
});

describe("searchMemories", () => {
  const rows = [
    at(1, { text: "the gate records its own evidence", tags: ["gate"] }),
    at(2, { text: "unrelated", tags: ["rf"], links: [{ ref: "bsc-graph--methods.rs", rel: "about" }] }),
  ];
  it("matches text, tags and link targets, case-insensitively", () => {
    expect(searchMemories(rows, "EVIDENCE")).toHaveLength(1);
    expect(searchMemories(rows, "rf")).toHaveLength(1);
    expect(searchMemories(rows, "bsc-graph")).toHaveLength(1);
  });
  it("keeps everything for an empty query — never reads as an empty store", () => {
    expect(searchMemories(rows, "   ")).toHaveLength(2);
  });
});

describe("summarize", () => {
  it("counts each facet, `edges` across every memory, and the per-kind tab counts", () => {
    const s = summarize([
      at(1, { horizon: "now", kind: "lesson", links: [{ ref: "a.rs", rel: "about" }, { ref: "b.rs", rel: "about" }] }),
      at(2, { horizon: "future", kind: "highlight" }),
      at(3, { horizon: "now", status: "done", kind: "lesson" }),
    ]);
    expect(s).toEqual({
      total: 3, now: 2, future: 1, unlinked: 2, open: 2, edges: 2,
      byKind: { lesson: 2, highlight: 1, record: 0, ambient: 0, note: 0 },
    });
  });

  it("counts every declared kind, so a tab badge is never undefined", () => {
    const s = summarize([]);
    for (const k of KINDS) expect(s.byKind[k]).toBe(0);
  });
});

describe("tagCounts", () => {
  it("ranks most-used first, then alphabetical", () => {
    const rows = [at(1, { tags: ["gate", "rust"] }), at(2, { tags: ["gate"] }), at(3, { tags: ["a"] })];
    expect(tagCounts(rows)).toEqual([{ tag: "gate", n: 2 }, { tag: "a", n: 1 }, { tag: "rust", n: 1 }]);
  });
});

describe("linkKind / targetLabel — everything is a node, and a target may say which", () => {
  it("takes an EXPLICIT node-type prefix over any heuristic", () => {
    // The case shape inference structurally cannot solve: a feature slug and a plan ref are the same
    // shape, so the only way to tell them apart is to be told.
    expect(linkKind("feature:auth")).toBe("feature");
    expect(linkKind("plan:auth")).toBe("plan");
    expect(linkKind("session:studio-code:director")).toBe("session");
    expect(linkKind("Record:bsc-graph--methods.rs")).toBe("record");
  });

  it("strips the prefix for display — the chip already says what type it is", () => {
    expect(targetLabel("feature:auth")).toBe("auth");
    expect(targetLabel("session:studio-code:director")).toBe("studio-code:director");
    expect(targetLabel("bsc-graph--methods.rs")).toBe("bsc-graph--methods.rs");
  });

  it("does not half-match a degenerate prefix", () => {
    expect(linkKind("feature:")).toBe("ref");
    expect(targetLabel("feature:")).toBe("feature:");
  });
});

describe("linkKind — the front half of the back-reference resolver", () => {
  it("reads an all-digit target as another memory (an id is epoch nanos)", () => {
    expect(linkKind("1757300000000000000")).toBe("memory");
  });
  it("reads a `#` target as a symbol anchor", () => {
    expect(linkKind("bsc-disk--sweep.rs#DEFAULT_DAYS")).toBe("symbol");
  });
  it("reads a method-first record id, and a bare module filename", () => {
    expect(linkKind("bsc-graph--methods.rs")).toBe("record");
    expect(linkKind("app-registry.ts")).toBe("record");
  });
  it("reads a kebab slug as a plan ref", () => {
    expect(linkKind("memory-nodes-in-the-knowledge-graph")).toBe("plan");
  });
  it("falls back to `ref` rather than failing on a shape it does not know", () => {
    expect(linkKind("SomethingElse")).toBe("ref");
    expect(linkKind("")).toBe("ref");
  });
});

describe("relativeAge", () => {
  const now = 1_000_000_000;
  it("reports an absent timestamp as unknown, never as 'just now'", () => {
    expect(relativeAge(0, now)).toBe("unknown");
  });
  it("shortens as it ages", () => {
    expect(relativeAge(now - 5_000, now)).toBe("just now");
    expect(relativeAge(now - 5 * 60_000, now)).toBe("5m ago");
    expect(relativeAge(now - 3 * 3_600_000, now)).toBe("3h ago");
    expect(relativeAge(now - 2 * 86_400_000, now)).toBe("2d ago");
    expect(relativeAge(now - 60 * 86_400_000, now)).toBe("2mo ago");
  });
});

describe("buildGraph — everything is a node", () => {
  const a = at(1, { kind: "lesson", text: "a lesson about the gate", links: [{ ref: "bsc-graph--methods.rs", rel: "about" }] });
  const b = at(2, { kind: "highlight", text: "a decision", links: [{ ref: a.id, rel: "because" }, { ref: "feature:auth", rel: "about" }] });
  const orphan = at(3, { kind: "note", text: "nothing points here" });

  it("makes a node for every memory and a STUB for every non-memory target", () => {
    const g = buildGraph([a, b, orphan]);
    const ids = g.nodes.map((n) => n.id).sort();
    expect(ids).toEqual([a.id, b.id, orphan.id, "bsc-graph--methods.rs", "feature:auth"].sort());
    const stub = g.nodes.find((n) => n.id === "feature:auth")!;
    expect(stub.isMemory).toBe(false);
    expect(stub.kind).toBe("feature");
    // The stub shows the readable half — the chip's own type already says "feature".
    expect(stub.label).toBe("auth");
  });

  it("carries the memory's own kind onto its node, for colouring", () => {
    const g = buildGraph([a, b, orphan]);
    expect(g.nodes.find((n) => n.id === a.id)!.kind).toBe("lesson");
    expect(g.nodes.find((n) => n.id === b.id)!.kind).toBe("highlight");
  });

  it("links two memories directly when the target is one of them", () => {
    const g = buildGraph([a, b, orphan]);
    const e = g.edges.find((x) => x.from === b.id && x.to === a.id)!;
    expect(e.rel).toBe("because");
    expect(g.nodes.find((n) => n.id === a.id)!.isMemory).toBe(true);
  });

  it("keeps TWO edges when one memory points at one target under two relationships", () => {
    // `about` and `contradicts` to the same record are opposite claims. Collapsing them to one edge
    // would silently drop whichever arrived second.
    const both = at(4, { links: [{ ref: "x.rs", rel: "about" }, { ref: "x.rs", rel: "contradicts" }] });
    const g = buildGraph([both]);
    expect(g.edges).toHaveLength(2);
    expect(g.edges.map((e) => e.rel).sort()).toEqual(["about", "contradicts"]);
    expect(g.nodes.filter((n) => n.id === "x.rs")).toHaveLength(1);
  });

  it("counts an ORPHAN — a memory nothing can traverse to", () => {
    const g = buildGraph([a, b, orphan]);
    expect(g.orphans).toBe(1);
    expect(g.nodes.find((n) => n.id === orphan.id)!.degree).toBe(0);
  });

  it("never calls a stub an orphan — a stub exists BECAUSE an edge created it", () => {
    const g = buildGraph([a]);
    expect(g.nodes.find((n) => n.id === "bsc-graph--methods.rs")!.degree).toBe(1);
    expect(g.orphans).toBe(0);
  });

  it("counts degree in BOTH directions, so a pointed-at memory is not an orphan", () => {
    const g = buildGraph([a, b]);
    // `a` points out once and is pointed at once by `b`.
    expect(g.nodes.find((n) => n.id === a.id)!.degree).toBe(2);
  });

  it("truncates a long memory to a card-sized label without losing the node", () => {
    const long = at(5, { text: "x".repeat(400) });
    const n = buildGraph([long]).nodes[0];
    expect(n.label.length).toBeLessThan(100);
    expect(n.label.endsWith("…")).toBe(true);
    expect(n.id).toBe(long.id);
  });

  it("survives an empty store and a blank target", () => {
    expect(buildGraph([])).toEqual({ nodes: [], edges: [], orphans: 0 });
    const blank = at(6, { links: [{ ref: "   ", rel: "about" }] });
    const g = buildGraph([blank]);
    expect(g.edges).toHaveLength(0);
    expect(g.nodes).toHaveLength(1);
  });
});

