// The Memory feature's pure domain — no React, no Tauri, so every rule below is unit-testable
// without a store or a render.
//
// `bsc memory` is the surface that catches what a session LEARNS but has no plan item for: a
// finding, a decision, a lesson, a parked thread. The change record says what a slice DID; this
// says what we now KNOW. It is a graph rather than a log — each memory carries typed edges to the
// things it is about (a graph record id, a plan ref, another memory, a symbol anchor) — and this
// module is the shape of `bsc memory list --json` plus the presentation decisions that go with it.
//
// NOTHING HERE RE-DERIVES A BACKEND RULE. Ordering and filtering mirror `filter_and_order` in
// `crates/bsc-memory` because the screen and the CLI must agree about what "newest first" means;
// the horizon default mirrors `default_horizon` for the same reason. Where a rule already exists in
// Rust this module PARSES its output rather than recomputing it.

/**
 * The KINDS of memory, mirroring `bsc_memory::KINDS` and in the same reading order.
 *
 * They are not interchangeable, and that is the whole reason this is the workspace's page axis rather
 * than a filter: each kind has different PROVENANCE and a different lifecycle. A lesson comes from a
 * session getting something wrong. A highlight comes from a conversation and should persist
 * indefinitely — it is the kind with no other home in this system, which is why it is the one worth
 * having a capture habit for. A record note comes from a comment inside code. An ambient capture comes
 * from the always-on ear and is a candidate, not yet a memory anyone chose to keep.
 *
 * `note` is last because it is the ABSENCE of a classification, not a peer: it is what an unclassified
 * memory reads as, so nothing is ever mislabelled by omission.
 */
export const KINDS = ["lesson", "highlight", "record", "ambient", "note"] as const;
export type Kind = (typeof KINDS)[number];

/** How each kind reads, and the one line saying what belongs in it. The blurb is rendered on the page:
 *  two words on a tab cannot carry the distinction, and the distinction is the point. */
export const KIND_META: Record<Kind, { label: string; blurb: string }> = {
  lesson: {
    label: "Lessons",
    blurb: "What we got wrong, and the rule that came out of it. A fix repairs one instance; the rule is what stops the next one.",
  },
  highlight: {
    label: "Highlights",
    blurb: "Discussions and decisions that should persist indefinitely. The kind with no other home — everything else here is harvested from a store that already exists.",
  },
  record: {
    label: "Records",
    blurb: "Comments explaining why a code record is the way it is. Extracted, never moved: the comment stays in the code, and this is the traversable copy.",
  },
  ambient: {
    label: "Ambient",
    blurb: "What the always-on ear caught — the half-formed thought you did not know to record. A review queue: promote one to a lesson or a highlight, or mark it done.",
  },
  note: {
    label: "Unclassified",
    blurb: "Captured without a kind. Not a category — a queue. Give each one a kind so it appears where someone would look for it.",
  },
};

/** Narrow an arbitrary value to a kind. Unknown reads as `note`, mirroring `default_kind` — an
 *  unreadable kind must present as UNCLASSIFIED rather than being filed under a real one. */
export function asKind(raw: unknown): Kind {
  return KINDS.includes(raw as Kind) ? (raw as Kind) : "note";
}

/** The two horizons, mirroring `bsc_memory::{HORIZON_NOW, HORIZON_FUTURE}`. */
export const HORIZONS = ["now", "future"] as const;
export type Horizon = (typeof HORIZONS)[number];

/** The status vocabulary, mirroring the `status` field `bsc memory add` / `done` write. */
export const MEMORY_STATUSES = ["open", "done"] as const;
export type MemoryStatus = (typeof MEMORY_STATUSES)[number];

/** The neutral relationship, mirroring `bsc_memory::DEFAULT_REL`. */
export const DEFAULT_REL = "related";

/** A typed edge out of a memory. `ref` is any target — a graph record id, a plan ref, another
 *  memory's id, a symbol anchor — and `rel` names the relationship. `rel` is a FREE string on the
 *  backend on purpose (the vocabulary grows from use), so this type does not narrow it. */
export interface MemoryLink {
  ref: string;
  rel: string;
}

/** One row as `bsc memory list --json` emits it. */
export interface MemoryEntry {
  id: string;
  text: string;
  tags: string[];
  createdAtMs: number;
  status: MemoryStatus;
  horizon: Horizon;
  kind: Kind;
  links: MemoryLink[];
}

/** The part of a target after its `<type>:` prefix, for display — `feature:auth` reads as `auth` once
 *  the chip already says it is a feature. Unprefixed targets are returned whole. */
export function targetLabel(ref: string): string {
  const t = ref.trim();
  const ty = NODE_TYPES.find((x) => t.length > x.length + 1 && t.slice(0, x.length + 1).toLowerCase() === `${x}:`);
  return ty ? t.slice(ty.length + 1) : t;
}

/** What a link's `ref` POINTS AT — an explicit `<type>:` prefix when it carries one, else inferred
 *  from its shape. The backend stores a bare string — it
 *  deliberately does not validate the target, because a memory may point at something that does not
 *  exist yet — so the kind is derived here, and only to decide how the chip renders.
 *
 *  This is the front half of the back-reference resolver: a chip that knows it names a graph record
 *  is a chip that can navigate to one. An unrecognised shape is `ref`, never an error — a wrong
 *  guess would make a real edge unrenderable. */
export type LinkKind = "memory" | "symbol" | "record" | "plan" | "feature" | "session" | "ref";

/** The node types a target may name EXPLICITLY, as a `<type>:` prefix — mirroring
 *  `bsc_memory::NODE_TYPES`. Shape inference covers the unambiguous forms; these exist for the ones
 *  that are not, because a feature slug and a plan ref are the same shape and a session id is whatever
 *  the fleet minted. Everything is a node, so adding a type is naming one here. */
export const NODE_TYPES = ["memory", "record", "plan", "feature", "session", "symbol"] as const;

/** A memory id is nanoseconds since the epoch as a string, so an all-digit target is another
 *  memory. Checked FIRST: a numeric id matches nothing else, and every later rule is a heuristic. */
const MEMORY_ID = /^\d{10,}$/;
/** `<record-id>#SYMBOL` — the anchor form. The symbol layer does not resolve yet; the shape is
 *  recognised anyway so a memory written against it renders as the anchor it is. */
const SYMBOL_ANCHOR = /#/;
/** A graph record id: the method-first `a--b.rs` form, or any bare `<name>.<ext>`. */
const RECORD_ID = /(^|--)[^/]+\.(rs|ts|tsx|json|md)$/;

export function linkKind(ref: string): LinkKind {
  const t = ref.trim();
  if (!t) return "ref";
  // An EXPLICIT prefix wins over every heuristic below. It is the only thing that can distinguish a
  // feature from a plan ref, and a caller that bothered to say so is never second-guessed.
  const prefixed = NODE_TYPES.find((ty) => t.length > ty.length + 1 && t.slice(0, ty.length + 1).toLowerCase() === `${ty}:`);
  if (prefixed) return prefixed;
  if (MEMORY_ID.test(t)) return "memory";
  if (SYMBOL_ANCHOR.test(t)) return "symbol";
  if (RECORD_ID.test(t)) return "record";
  // A plan ref is a bare kebab slug — the branch name, the issue ref and the change ref are one
  // string here, which is exactly what makes it worth badging separately from an unknown target.
  if (/^[a-z0-9]+(-[a-z0-9]+)+$/.test(t)) return "plan";
  return "ref";
}

/** Narrow an arbitrary value to a horizon. Unknown reads as `now`, mirroring `default_horizon`:
 *  a memory whose horizon was never set is applicable to what is implemented, not aspirational. */
export function asHorizon(raw: unknown): Horizon {
  return HORIZONS.includes(raw as Horizon) ? (raw as Horizon) : "now";
}

/** Narrow an arbitrary value to a status. Unknown reads as `open` — a memory whose status we cannot
 *  read has not been shown to be handled, and rendering it as `done` would hide it. */
export function asStatus(raw: unknown): MemoryStatus {
  return MEMORY_STATUSES.includes(raw as MemoryStatus) ? (raw as MemoryStatus) : "open";
}

/** Accept BOTH the typed edge `{ref, rel}` and the legacy bare string, exactly as `de_links` does
 *  in `crates/bsc-memory` — a store written before typed edges is still a valid store. */
function normalizeLink(raw: unknown): MemoryLink | null {
  if (typeof raw === "string") {
    const ref = raw.trim();
    return ref ? { ref, rel: DEFAULT_REL } : null;
  }
  if (raw && typeof raw === "object") {
    const o = raw as Record<string, unknown>;
    const ref = typeof o.ref === "string" ? o.ref.trim() : "";
    if (!ref) return null;
    const rel = typeof o.rel === "string" && o.rel.trim() ? o.rel.trim() : DEFAULT_REL;
    return { ref, rel };
  }
  return null;
}

function normalizeEntry(raw: unknown): MemoryEntry | null {
  if (!raw || typeof raw !== "object") return null;
  const o = raw as Record<string, unknown>;
  const id = typeof o.id === "string" ? o.id : "";
  const text = typeof o.text === "string" ? o.text : "";
  // A row with no id cannot be keyed, and a row with no text has nothing to show. Both are dropped
  // rather than rendered as a blank line — this is a verbatim-JSON store with no schema migration,
  // so a malformed row is a possibility rather than an impossibility.
  if (!id || !text.trim()) return null;
  // The wire is serde's default naming (`created_at_ms`). The camelCase spelling is accepted too so
  // a future rename on the backend does not silently zero every timestamp on this screen.
  const created = o.created_at_ms ?? o.createdAtMs;
  return {
    id,
    text,
    tags: Array.isArray(o.tags) ? o.tags.filter((t): t is string => typeof t === "string") : [],
    createdAtMs: typeof created === "number" ? created : 0,
    status: asStatus(o.status),
    horizon: asHorizon(o.horizon),
    kind: asKind(o.kind),
    links: Array.isArray(o.links)
      ? o.links.map(normalizeLink).filter((l): l is MemoryLink => l !== null)
      : [],
  };
}

/** Parse whatever `bsc memory list --json` returned. Tolerant on purpose: a bare array, or an
 *  object wrapping one, and any row it cannot read is skipped rather than failing the whole page. */
export function parseMemories(raw: unknown): MemoryEntry[] {
  let value: unknown = raw;
  if (typeof value === "string") {
    try {
      value = JSON.parse(value);
    } catch {
      return [];
    }
  }
  if (value && typeof value === "object" && !Array.isArray(value)) {
    const wrapped = (value as Record<string, unknown>).memories;
    if (Array.isArray(wrapped)) value = wrapped;
  }
  if (!Array.isArray(value)) return [];
  return value.map(normalizeEntry).filter((m): m is MemoryEntry => m !== null);
}

/** Newest first — the same order `filter_and_order` produces, so the screen and `bsc memory list`
 *  never disagree about which memory is the most recent one. Ties break on id, which is also time. */
export function sortMemories(items: MemoryEntry[]): MemoryEntry[] {
  return [...items].sort((a, b) => b.createdAtMs - a.createdAtMs || (a.id < b.id ? 1 : a.id > b.id ? -1 : 0));
}

/**
 * The Memory workspace's page tabs: the GRAPH, then one page per kind.
 *
 * The axis is KIND rather than horizon because the kinds have different provenance and different
 * lifecycles, so they are read differently — where `now` and `future` are two readings of the same
 * pile. Horizon survives as a filter WITHIN a page, which is where it belongs: a highlight can be a
 * hope, and a lesson never is.
 *
 * `graph` leads because everything here is a node. A list is the readable index for one kind; the
 * graph is the only view in which an edge — the thing that makes this a memory GRAPH rather than a
 * memory log — is visible at all, and in which an edgeless node is visibly floating rather than
 * needing a tab of its own to explain it.
 */
export const MEMORY_TABS = ["graph", ...KINDS] as const;
export type MemoryTab = (typeof MEMORY_TABS)[number];

export const TAB_LABEL: Record<MemoryTab, string> = {
  graph: "Graph",
  ...Object.fromEntries(KINDS.map((k) => [k, KIND_META[k].label])),
} as Record<MemoryTab, string>;

/** What each page is FOR, in one line. */
export const TAB_BLURB: Record<MemoryTab, string> = {
  graph: "Every memory as a node, and every typed edge to the record, feature, session or memory it is about. A node with no edges is one nothing can traverse to.",
  ...Object.fromEntries(KINDS.map((k) => [k, KIND_META[k].blurb])),
} as Record<MemoryTab, string>;

/** The rows one page shows. `graph` is every memory — it is the whole graph, not a sixth kind. */
export function selectTab(items: MemoryEntry[], tab: MemoryTab): MemoryEntry[] {
  if (tab === "graph") return items;
  return items.filter((m) => m.kind === tab);
}

/** Free-text narrowing over the text and the tags. Case-insensitive; an empty query keeps everything
 *  (never "matches nothing", which would read as an empty store). */
export function searchMemories(items: MemoryEntry[], query: string): MemoryEntry[] {
  const q = query.trim().toLowerCase();
  if (!q) return items;
  return items.filter(
    (m) => m.text.toLowerCase().includes(q) || m.tags.some((t) => t.includes(q)) || m.links.some((l) => l.ref.toLowerCase().includes(q)),
  );
}

export interface MemorySummary {
  total: number;
  now: number;
  future: number;
  unlinked: number;
  open: number;
  edges: number;
  /** How many memories carry each kind — the tab counts, and the size of the `note` queue. */
  byKind: Record<Kind, number>;
}

/** The counts the header reports. `edges` is the total across every memory — the one number that
 *  says whether this is a graph yet or still a pile. */
export function summarize(items: MemoryEntry[]): MemorySummary {
  return {
    total: items.length,
    now: items.filter((m) => m.horizon === "now").length,
    future: items.filter((m) => m.horizon === "future").length,
    unlinked: items.filter((m) => m.links.length === 0).length,
    open: items.filter((m) => m.status === "open").length,
    edges: items.reduce((n, m) => n + m.links.length, 0),
    byKind: Object.fromEntries(KINDS.map((k) => [k, items.filter((m) => m.kind === k).length])) as Record<Kind, number>,
  };
}

/** The tag vocabulary present in the store, most-used first then alphabetical — the discover step,
 *  since a tag filter is unreachable by anyone who cannot first learn which tags exist. */
export function tagCounts(items: MemoryEntry[]): { tag: string; n: number }[] {
  const counts = new Map<string, number>();
  for (const m of items) for (const t of m.tags) counts.set(t, (counts.get(t) ?? 0) + 1);
  return [...counts.entries()]
    .map(([tag, n]) => ({ tag, n }))
    .sort((a, b) => b.n - a.n || a.tag.localeCompare(b.tag));
}

/** How long ago, in the shortest form that is still true. Absent reads as `unknown`, never as
 *  "just now" — a missing timestamp is not a recent one. */
export function relativeAge(ms: number, nowMs: number): string {
  if (!ms) return "unknown";
  const s = Math.max(0, Math.floor((nowMs - ms) / 1000));
  if (s < 60) return "just now";
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  const d = Math.floor(h / 24);
  return d < 30 ? `${d}d ago` : `${Math.floor(d / 30)}mo ago`;
}

/** One node in the rendered memory graph: a memory itself, or a STUB standing for a non-memory target
 *  an edge points at (a record, a feature, a session, a plan ref). */
export interface GraphNode {
  id: string;
  kind: LinkKind | Kind;
  /** What the node shows. A memory's text is truncated; a stub shows its target label. */
  label: string;
  /** True for a memory in this store; false for a stub we know only as an edge target. */
  isMemory: boolean;
  /** How many edges touch it, in either direction — the degree, which is what makes an orphan visible. */
  degree: number;
}

export interface GraphEdge {
  from: string;
  to: string;
  rel: string;
}

export interface MemoryGraph {
  nodes: GraphNode[];
  edges: GraphEdge[];
  /** Memory nodes with no edge at all — nothing can traverse to them. */
  orphans: number;
}

/** How much of a memory's text a node card shows before it is cut. */
const NODE_LABEL_CHARS = 72;

function truncate(text: string, n: number): string {
  const t = text.trim().replace(/\s+/g, " ");
  return t.length <= n ? t : `${t.slice(0, n - 1).trimEnd()}…`;
}

/**
 * Build the node/edge graph for a set of memories.
 *
 * A target that is ITSELF a memory in this set becomes an edge between two memory nodes; a target that
 * is not becomes a STUB node — because "everything is a node", and an edge to a record or a feature is
 * the whole reason this store is a graph rather than a tagged list. A stub is deliberately NOT resolved
 * against the other stores here: this module is pure, and a stub carries enough (its id and its kind)
 * for the renderer to offer the cross-graph jump.
 *
 * A memory linking to a target more than once under different relationships yields one node and TWO
 * edges — `about` and `contradicts` to the same record are two different claims, and collapsing them
 * would silently drop one.
 */
export function buildGraph(items: MemoryEntry[]): MemoryGraph {
  const byId = new Map(items.map((m) => [m.id, m]));
  const nodes = new Map<string, GraphNode>();
  const edges: GraphEdge[] = [];
  const degree = new Map<string, number>();
  const bump = (id: string) => degree.set(id, (degree.get(id) ?? 0) + 1);

  for (const m of items) {
    nodes.set(m.id, { id: m.id, kind: m.kind, label: truncate(m.text, NODE_LABEL_CHARS), isMemory: true, degree: 0 });
  }
  for (const m of items) {
    for (const l of m.links) {
      const target = l.ref.trim();
      if (!target) continue;
      if (!nodes.has(target)) {
        // A stub. It may still be a memory we simply were not given (a filtered view), so its kind is
        // read from the target's own shape rather than assumed to be external.
        nodes.set(target, {
          id: target,
          kind: byId.has(target) ? "memory" : linkKind(target),
          label: targetLabel(target),
          isMemory: byId.has(target),
          degree: 0,
        });
      }
      edges.push({ from: m.id, to: target, rel: l.rel });
      bump(m.id);
      bump(target);
    }
  }
  for (const n of nodes.values()) n.degree = degree.get(n.id) ?? 0;
  const list = [...nodes.values()];
  return {
    nodes: list,
    edges,
    // Only MEMORY nodes can be orphans. A stub always has the edge that created it, by construction.
    orphans: list.filter((n) => n.isMemory && n.degree === 0).length,
  };
}

/** Node box + spacing, in world (design-space) px. Exported so the renderer draws edges to the same
 *  geometry the layout computed, rather than a second set of constants free to disagree. */
export const NODE_W = 230;
export const NODE_H = 78;
const COL_GAP = 110;
const ROW_GAP = 26;
const PAD = 60;

/** The layout's column order: the memory kinds in reading order, then one column for the STUBS —
 *  the records, features and sessions memories point AT. Stubs sit last because the graph reads
 *  left-to-right as "what we know" → "what it is about". */
export const LAYOUT_COLUMNS = [...KINDS, "target"] as const;
export type LayoutColumn = (typeof LAYOUT_COLUMNS)[number];

export interface Placed extends GraphNode {
  x: number;
  y: number;
  column: LayoutColumn;
}

export interface GraphLayout {
  nodes: Placed[];
  edges: (GraphEdge & { x1: number; y1: number; x2: number; y2: number })[];
  world: { w: number; h: number };
}

/**
 * Place a memory graph deterministically: one column per kind, plus a final column for the non-memory
 * targets, and within a column the most-connected node first.
 *
 * DETERMINISTIC ON PURPOSE — no physics, no randomness. A force layout re-arranges itself on every
 * render and on every data change, so the same graph never looks the same twice and a node you were
 * reading moves out from under you. Ordering by degree puts the hubs — the records everything has an
 * opinion about — at the top of their column, which is the thing worth seeing first.
 *
 * An EMPTY column takes no width, so a store with only lessons renders two columns rather than six
 * with four blank gutters.
 */
export function layoutGraph(graph: MemoryGraph): GraphLayout {
  const columnOf = (n: GraphNode): LayoutColumn =>
    n.isMemory && (KINDS as readonly string[]).includes(n.kind) ? (n.kind as LayoutColumn) : "target";

  const byColumn = new Map<LayoutColumn, GraphNode[]>();
  for (const n of graph.nodes) {
    const c = columnOf(n);
    const list = byColumn.get(c) ?? [];
    list.push(n);
    byColumn.set(c, list);
  }
  // Most-connected first, then by id so the order never depends on input order.
  for (const list of byColumn.values()) {
    list.sort((a, b) => b.degree - a.degree || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  }

  const placed: Placed[] = [];
  let x = PAD;
  let tallest = 0;
  for (const c of LAYOUT_COLUMNS) {
    const list = byColumn.get(c);
    if (!list || list.length === 0) continue;
    list.forEach((n, i) => {
      placed.push({ ...n, x, y: PAD + i * (NODE_H + ROW_GAP), column: c });
    });
    tallest = Math.max(tallest, list.length);
    x += NODE_W + COL_GAP;
  }

  const at = new Map(placed.map((n) => [n.id, n]));
  const edges = graph.edges.flatMap((e) => {
    const a = at.get(e.from);
    const b = at.get(e.to);
    // An edge whose endpoint was not placed is DROPPED rather than drawn to (0,0) — a line to the
    // corner reads as a real relationship to nothing.
    if (!a || !b) return [];
    return [{ ...e, x1: a.x + NODE_W, y1: a.y + NODE_H / 2, x2: b.x, y2: b.y + NODE_H / 2 }];
  });

  return {
    nodes: placed,
    edges,
    world: {
      w: Math.max(x - COL_GAP + PAD, NODE_W + PAD * 2),
      h: Math.max(PAD * 2 + tallest * (NODE_H + ROW_GAP) - ROW_GAP, NODE_H + PAD * 2),
    },
  };
}
